package com.gamehubstore.review_mscv.controllers; import com.gamehubstore.review_mscv.models.Review; import com.gamehubstore.review_mscv.services.ReviewService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/reviews") public class ReviewController { private final ReviewService service; public ReviewController(ReviewService s){service=s;} @GetMapping public List<Review> all(){return service.all();} @GetMapping("/product/{id}") public List<Review> byProduct(@PathVariable Long id){return service.byProduct(id);} @GetMapping("/user/{id}") public List<Review> byUser(@PathVariable Long id){return service.byUser(id);} @GetMapping("/{id}") public Review byId(@PathVariable Long id){return service.byId(id);} @PostMapping public ResponseEntity<Review> create(@Valid @RequestBody Review r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));} @PutMapping("/{id}") public Review update(@PathVariable Long id,@Valid @RequestBody Review r){return service.update(id,r);} @DeleteMapping("/{id}") public ResponseEntity<Void> moderate(@PathVariable Long id){service.moderate(id);return ResponseEntity.noContent().build();} }
